public class Main {
    public static void main(String[] args) {
        int n = 16;
        int[] data = new int[1];              // dynamic array, capacity starts at 1
        int size = 0, copies = 0;
        for (int v = 1; v <= n; v++) {
            if (size == data.length) {        // full: move everything to a block twice as big
                int[] bigger = new int[data.length * 2];
                for (int i = 0; i < size; i++) { bigger[i] = data[i]; copies++; }
                data = bigger;
            }
            data[size++] = v;                 // the append itself is one write
        }
        System.out.println("appends: " + n + ", elements copied by resizes: " + copies);
        // a[i] is one address calculation (base + i * slotSize), whatever i is
        System.out.println("a[10] read in one step: " + data[10]);
        // Insert 99 at the front: every element must move one slot right
        int[] grown = new int[size + 1];
        int shifts = 0;
        for (int i = size - 1; i >= 0; i--) { grown[i + 1] = data[i]; shifts++; }
        grown[0] = 99;
        System.out.println("front insert of 99 shifted " + shifts + " elements");
        System.out.println("first five now: " + grown[0] + " " + grown[1] + " " + grown[2] + " " + grown[3] + " " + grown[4]);
        // Time: read O(1), append O(1) amortized (15 copies for 16 appends), front insert O(N). Space: O(N).
    }
}

