#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 16;
    int cap = 1, size = 0, copies = 0;
    int* data = new int[cap];             // dynamic array, capacity starts at 1
    for (int v = 1; v <= n; v++) {
        if (size == cap) {                // full: move everything to a block twice as big
            int* bigger = new int[cap * 2];
            for (int i = 0; i < size; i++) { bigger[i] = data[i]; copies++; }
            delete[] data;
            data = bigger;
            cap *= 2;
        }
        data[size++] = v;                 // the append itself is one write
    }
    cout << "appends: " << n << ", elements copied by resizes: " << copies << "\n";
    // a[i] is one address calculation (base + i * slotSize), whatever i is
    cout << "a[10] read in one step: " << data[10] << "\n";
    // Insert 99 at the front: every element must move one slot right
    vector<int> grown(size + 1);
    int shifts = 0;
    for (int i = size - 1; i >= 0; i--) { grown[i + 1] = data[i]; shifts++; }
    grown[0] = 99;
    cout << "front insert of 99 shifted " << shifts << " elements\n";
    cout << "first five now: " << grown[0] << " " << grown[1] << " " << grown[2] << " " << grown[3] << " " << grown[4] << "\n";
    delete[] data;
    // Time: read O(1), append O(1) amortized (15 copies for 16 appends), front insert O(N). Space: O(N).
    return 0;
}

