import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {3, 1, 4, 1, 5, 9, 2, 6};
        int n = a.length;
        // Padded prefix array: p[0] = 0 and p[i + 1] = total of the first i + 1 items
        long[] p = new long[n + 1];             // long, so big totals do not overflow
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];
        System.out.println("A = " + Arrays.toString(a));
        System.out.println("P = " + Arrays.toString(p));
        int[][] queries = {{0, 7}, {2, 5}, {3, 3}};
        for (int[] q : queries) {
            int l = q[0], r = q[1];
            // Reading at R minus the reading just before L
            long sum = p[r + 1] - p[l];
            System.out.println("sum(" + l + ".." + r + ") = P[" + (r + 1) + "] - P[" + l + "] = " + sum);
        }
        // Time: O(N) to build, O(1) per query. Space: O(N).
    }
}

