#include <bits/stdc++.h>
using namespace std;

template <class T> string show(const vector<T>& v) {
    string s = "[";
    for (size_t i = 0; i < v.size(); i++) { if (i) s += ", "; s += to_string(v[i]); }
    return s + "]";
}

int main() {
    vector<int> a = {3, 1, 4, 1, 5, 9, 2, 6};
    int n = a.size();
    // Padded prefix array: p[0] = 0 and p[i + 1] = total of the first i + 1 items
    vector<long long> p(n + 1, 0);          // long long, so big totals do not overflow
    for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];
    cout << "A = " << show(a) << "\n";
    cout << "P = " << show(p) << "\n";
    vector<pair<int, int>> queries = {{0, 7}, {2, 5}, {3, 3}};
    for (auto [l, r] : queries) {
        // Reading at R minus the reading just before L
        long long sum = p[r + 1] - p[l];
        cout << "sum(" << l << ".." << r << ") = P[" << r + 1 << "] - P[" << l << "] = " << sum << "\n";
    }
    // Time: O(N) to build, O(1) per query. Space: O(N).
    return 0;
}

