import java.util.Arrays;

public class Main {
    static void kadane(int[] a) {
        long cur = a[0], best = a[0];          // start from a[0], not 0, for all-negative input
        int start = 0, bestL = 0, bestR = 0;
        for (int i = 1; i < a.length; i++) {
            if (cur < 0) { cur = a[i]; start = i; }   // a negative run only hurts: start fresh here
            else cur += a[i];                         // otherwise extend the run ending at i - 1
            if (cur > best) { best = cur; bestL = start; bestR = i; }
        }
        System.out.println("A = " + Arrays.toString(a));
        System.out.println("max subarray sum = " + best + " (indices " + bestL + ".." + bestR + ")");
    }

    public static void main(String[] args) {
        kadane(new int[]{-2, 1, -3, 4, -1, 2, 1, -5, 4});
        kadane(new int[]{-3, -1, -2});         // all negative: the answer is the largest single item
        // Time: O(N), one pass. Space: O(1).
    }
}

