import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {3, 1, 4, 1, 5};
        int n = a.length;
        System.out.println("A = " + Arrays.toString(a));
        // Slow check: add up every subarray one by one, O(N^2)
        long brute = 0;
        for (int l = 0; l < n; l++) {
            long run = 0;
            for (int r = l; r < n; r++) { run += a[r]; brute += run; }
        }
        // Fast way: a[i] is inside (i + 1) * (n - i) subarrays
        long fast = 0;
        for (int i = 0; i < n; i++) {
            long times = (long) (i + 1) * (n - i);   // cast to long before multiplying
            System.out.println("a[" + i + "] = " + a[i] + " appears in " + times + " subarrays");
            fast += a[i] * times;
        }
        System.out.println("brute force total = " + brute);
        System.out.println("contribution total = " + fast);
        // Time: O(N) for the contribution pass. Space: O(1).
    }
}

