import java.util.Arrays;

public class Main {
    static int trap(int[] h) {
        int l = 0, r = h.length - 1, leftMax = 0, rightMax = 0, water = 0;
        while (l <= r) {
            leftMax = Math.max(leftMax, h[l]);      // tallest bar seen from the left, including h[l]
            rightMax = Math.max(rightMax, h[r]);    // tallest bar seen from the right, including h[r]
            if (leftMax <= rightMax) {
                water += leftMax - h[l];            // right side has a wall at least this tall
                l++;
            } else {
                water += rightMax - h[r];           // mirror case: settle the right bar
                r--;
            }
        }
        return water;
    }

    public static void main(String[] args) {
        int[] h = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};
        System.out.println("heights = " + Arrays.toString(h));
        System.out.println("trapped water = " + trap(h));
        int[] v = {4, 2, 0, 3, 2, 5};
        System.out.println("heights = " + Arrays.toString(v));
        System.out.println("trapped water = " + trap(v));
        // Time: O(N), each step settles one bar. Space: O(1).
    }
}

