#include <bits/stdc++.h>
using namespace std;

int trap(const vector<int>& h) {
    int l = 0, r = (int)h.size() - 1, leftMax = 0, rightMax = 0, water = 0;
    while (l <= r) {
        leftMax = max(leftMax, h[l]);       // tallest bar seen from the left, including h[l]
        rightMax = max(rightMax, h[r]);     // tallest bar seen from the right, including h[r]
        if (leftMax <= rightMax) {
            water += leftMax - h[l];        // right side has a wall at least this tall
            l++;
        } else {
            water += rightMax - h[r];       // mirror case: settle the right bar
            r--;
        }
    }
    return water;
}

void run(const vector<int>& h) {
    cout << "heights = [";
    for (size_t i = 0; i < h.size(); i++) cout << (i ? ", " : "") << h[i];
    cout << "]\n" << "trapped water = " << trap(h) << "\n";
}

int main() {
    run({0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1});
    run({4, 2, 0, 3, 2, 5});
    // Time: O(N), each step settles one bar. Space: O(1).
    return 0;
}

