import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {16, 17, 4, 3, 5, 2};
        System.out.println("A = " + Arrays.toString(a));
        // A leader is bigger than everything to its right, so scan from the right
        int maxRight = Integer.MIN_VALUE, leaders = 0;
        StringBuilder found = new StringBuilder();
        for (int i = a.length - 1; i >= 0; i--) {
            if (a[i] > maxRight) {            // beats the carried summary of the right side
                leaders++;
                found.append(a[i]).append(" ");
                maxRight = a[i];              // carry the new maximum forward
            }
        }
        System.out.println("leaders (right to left): " + found.toString().trim() + " -> count " + leaders);

        String s = "abegag";
        // Pairs (i < j) with s[i] = 'a' and s[j] = 'g': carry the number of g's seen so far
        long pairs = 0;
        int gCount = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) == 'g') gCount++;
            else if (s.charAt(i) == 'a') pairs += gCount;   // this a pairs with every later g
        }
        System.out.println("s = " + s + ", a...g pairs = " + pairs);
        // Time: O(N) for each scan. Space: O(1).
    }
}

