import java.util.Arrays;

public class Main {
    static void print(String label, int[][] g) {
        System.out.println(label);
        for (int[] row : g) System.out.println("  " + Arrays.toString(row));
    }

    public static void main(String[] args) {
        int[][] g = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int n = g.length;
        print("square before:", g);
        // Step 1: transpose. Only c > r, or every pair would be swapped back again
        for (int r = 0; r < n; r++)
            for (int c = r + 1; c < n; c++) { int t = g[r][c]; g[r][c] = g[c][r]; g[c][r] = t; }
        // Step 2: reverse each row
        for (int r = 0; r < n; r++)
            for (int i = 0, j = n - 1; i < j; i++, j--) { int t = g[r][i]; g[r][i] = g[r][j]; g[r][j] = t; }
        print("square after (in place):", g);

        int[][] m = {{1, 2, 3}, {4, 5, 6}};
        int rows = m.length, cols = m[0].length;
        print("rectangle before (2 x 3):", m);
        // An R x C matrix becomes C x R, so it needs a new matrix: (r, c) -> (c, R - 1 - r)
        int[][] res = new int[cols][rows];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) res[c][rows - 1 - r] = m[r][c];
        print("rectangle after (3 x 2):", res);
        // Time: O(R * C). Space: O(1) for the square, O(R * C) for the rectangle.
    }
}

