public class Main {
    // Rows sorted and columns sorted: start top-right, each step drops a row or a column
    static String staircase(int[][] g, int target) {
        int r = 0, c = g[0].length - 1;
        while (r < g.length && c >= 0) {
            if (g[r][c] == target) return "(" + r + ", " + c + ")";
            if (g[r][c] > target) c--;      // everything below in this column is bigger too
            else r++;                       // everything to the left in this row is smaller too
        }
        return "not found";
    }

    // Fully sorted in reading order: binary search over the flat index 0..R*C-1
    static String flat(int[][] g, int target) {
        int cols = g[0].length, lo = 0, hi = g.length * cols - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int v = g[mid / cols][mid % cols];   // flat index -> (row, column)
            if (v == target) return "(" + mid / cols + ", " + mid % cols + ")";
            if (v < target) lo = mid + 1; else hi = mid - 1;
        }
        return "not found";
    }

    public static void main(String[] args) {
        int[][] a = {{1, 4, 7, 11}, {2, 5, 8, 12}, {3, 6, 9, 16}, {10, 13, 14, 17}};
        System.out.println("rows and columns sorted: 1 4 7 11 / 2 5 8 12 / 3 6 9 16 / 10 13 14 17");
        System.out.println("staircase, target 9 -> " + staircase(a, 9));
        System.out.println("staircase, target 15 -> " + staircase(a, 15));
        int[][] b = {{1, 3, 5, 7}, {10, 11, 16, 20}, {23, 30, 34, 60}};
        System.out.println("fully sorted: 1 3 5 7 / 10 11 16 20 / 23 30 34 60");
        System.out.println("binary search, target 16 -> " + flat(b, 16));
        System.out.println("binary search, target 4 -> " + flat(b, 4));
        // Time: staircase O(R + C), flat binary search O(log(R * C)). Space: O(1).
    }
}

