public class Main {
    public static void main(String[] args) {
        int[][] g = {{1, 2, -1, -4, -20}, {-8, -3, 4, 2, 1}, {3, 8, 10, 1, 3}, {-4, -1, 1, 7, -6}};
        int rows = g.length, cols = g[0].length;
        long best = Long.MIN_VALUE;
        int bt = 0, bb = 0, bl = 0, br = 0;
        for (int top = 0; top < rows; top++) {
            long[] col = new long[cols];               // col[c] = sum of column c from top to bottom
            for (int bottom = top; bottom < rows; bottom++) {
                for (int c = 0; c < cols; c++) col[c] += g[bottom][c];   // add the new row
                // Kadane on col: best run of neighbouring columns for this pair of rows
                long cur = 0;
                int start = 0;
                for (int c = 0; c < cols; c++) {
                    if (cur <= 0) { cur = col[c]; start = c; } else cur += col[c];
                    if (cur > best) { best = cur; bt = top; bb = bottom; bl = start; br = c; }
                }
            }
        }
        System.out.println("matrix rows: 1 2 -1 -4 -20 / -8 -3 4 2 1 / 3 8 10 1 3 / -4 -1 1 7 -6");
        System.out.println("max submatrix sum = " + best);
        System.out.println("rows " + bt + ".." + bb + ", columns " + bl + ".." + br);
        // Time: O(R^2 * C). Space: O(C). Transpose first if R > C.
    }
}

