import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int n = 8;
        int[][] updates = {{1, 4, 5}, {3, 6, 2}, {0, 2, -1}};   // {L, R, value to add}
        long[] d = new long[n + 1];                // one extra slot so d[R + 1] is always valid
        for (int[] u : updates) {
            d[u[0]] += u[2];                       // the value starts applying at L
            d[u[1] + 1] -= u[2];                   // and stops applying after R
            System.out.println("add " + u[2] + " to " + u[0] + ".." + u[1]);
        }
        // One prefix pass over d rebuilds the final array
        long[] a = new long[n];
        long run = 0;
        for (int i = 0; i < n; i++) { run += d[i]; a[i] = run; }
        System.out.println("final array = " + Arrays.toString(a));
        // A second prefix pass gives O(1) range sums
        long[] p = new long[n + 1];
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];
        System.out.println("sum(2..5) = " + (p[6] - p[2]));
        // Time: O(1) per update, O(N) to rebuild, O(1) per query. Space: O(N).
    }
}

