import java.util.Arrays;

public class Main {
    static int firstMissingPositive(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            // Send nums[i] to its home slot nums[i] - 1; stop on out-of-range values and duplicates
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {
                int home = nums[i] - 1;
                int t = nums[home]; nums[home] = nums[i]; nums[i] = t;
            }
        }
        for (int i = 0; i < n; i++)
            if (nums[i] != i + 1) return i + 1;    // first slot that does not hold its own number
        return n + 1;                              // 1..n are all present
    }

    public static void main(String[] args) {
        int[][] tests = {{3, 4, -1, 1}, {1, 2, 0}, {7, 8, 9, 11, 12}, {1, 1}};
        for (int[] t : tests) {
            String before = Arrays.toString(t);
            int ans = firstMissingPositive(t);
            System.out.println(before + " -> after placing " + Arrays.toString(t) + " -> answer " + ans);
        }
        // Time: O(N), each swap puts one value home for good. Space: O(1).
    }
}

