import java.util.Arrays;

public class Main {
    static int seed = 1;
    // Tiny fixed random generator, so every run produces the same tests
    static int next() { seed = (seed * 75 + 74) % 65537; return seed; }

    public static void main(String[] args) {
        int passed = 0, failedAt = -1;
        String report = "";
        for (int t = 1; t <= 200; t++) {
            int n = next() % 5 + 1;                          // small inputs are easy to debug
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = next() % 7 - 3;   // values -3..3, negatives included
            int l = next() % n, r = l + next() % (n - l);
            long[] p = new long[n + 1];
            for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];
            long brute = 0;                                  // the oracle: slow but obviously right
            for (int i = l; i <= r; i++) brute += a[i];
            long good = p[r + 1] - p[l];
            long bad = p[r] - p[l];                          // mixed conventions: silently drops a[r]
            if (good == brute) passed++;
            if (bad != brute && failedAt < 0) {
                failedAt = t;
                report = "A = " + Arrays.toString(a) + ", L = " + l + ", R = " + r + ": expected " + brute + ", buggy got " + bad;
            }
        }
        System.out.println("correct P[R+1] - P[L] passed " + passed + " of 200 random tests");
        System.out.println("buggy P[R] - P[L] first failed on test " + failedAt);
        System.out.println(report);
        // Time: O(tests * N) for the whole check. Space: O(N).
    }
}

